WITH with_windows AS (SELECT id, customer_id, order_date, channel, amount, discount, shipping_fee, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY shipping_fee, id) AS event_seq, AVG(amount) OVER (PARTITION BY customer_id ORDER BY shipping_fee, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS amount_avg_2_prior, AVG(discount) OVER w_running AS status_avg_discount, RANK() OVER (PARTITION BY status ORDER BY shipping_fee NULLS LAST) AS shipping_fee_rank FROM orders WINDOW w_running AS (PARTITION BY status, store_id)) SELECT s.id, s.customer_id, s.order_date, s.channel, s.amount, s.discount, s.shipping_fee, s.amount_avg_2_prior, s.status_avg_discount, CASE WHEN channel RLIKE '^(mobile|partner)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS channel_zone, (SELECT AVG(t2.monthly_fee) FROM subscriptions t2 WHERE t2.customer_id = s.customer_id) AS avg_subscription_monthly_fee FROM with_windows s ORDER BY customer_id DESC
